package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import java.io.*;
@WebServlet("/admin") public class AdminDashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);PlantDao plants=new PlantDao();r.setAttribute("plantCount",plants.countAll());r.setAttribute("reviewCount",plants.countReview());r.setAttribute("users",new UserDao().allUsers().size());r.setAttribute("logs",new AuditDao().recent(10));WebSupport.view(r,s,"admin/dashboard");}catch(Exception e){WebSupport.error(r,s,e,"管理概览暂时不可用。");}}}
